import { test, expect } from 'vitest';
import { renderToStaticMarkup } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './App';
import { DataTable } from './DataTable';
import { generateUsers } from './data';

const users = generateUsers(57);

test('App renders first page sorted by name', () => {
  const html = renderToStaticMarkup(<ThemeProvider theme="light"><App /></ThemeProvider>);
  const rows = html.match(/<tr[^>]*class="g-table__row/g) ?? [];
  expect(rows.length).toBe(10);
  expect(html).toContain('Показано 1–10 из 57');
  expect(html).toContain('Выбрано: 0 из 57');
  const names = [...html.matchAll(/user\d+@example\.com/g)].map((m) => m[0]);
  const byName = users.slice().sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' })).slice(0, 10).map((u) => u.email);
  expect(names).toEqual(byName);
  // checkbox column present, header has sort indicator
  expect((html.match(/g-table__selection-checkbox/g) ?? []).length).toBe(11);
  expect(html).toContain('g-table__sort g-table__sort_active');
});

test('DataTable with page size and desc sort', () => {
  const html = renderToStaticMarkup(
    <ThemeProvider theme="light">
      <DataTable
        data={users}
        columns={[{ id: 'age', name: 'Возраст', sortable: true }, { id: 'name', name: 'Имя' }]}
        defaultPageSize={20}
        defaultSortState={[{ column: 'age', order: 'desc' }]}
        selectedIds={['1', '2', '3']}
      />
    </ThemeProvider>,
  );
  expect((html.match(/<tr[^>]*class="g-table__row/g) ?? []).length).toBe(20);
  expect(html).toContain('Показано 1–20 из 57');
  expect(html).toContain('Выбрано: 3 из 57');
  expect(html).toContain('Снять выделение');
  const ages = [...html.matchAll(/<td[^>]*>(\d+)<\/td>/g)].map((m) => Number(m[1]));
  expect(ages.length).toBe(20);
  expect(ages).toEqual(ages.slice().sort((a, b) => b - a));
});

test('empty data', () => {
  const html = renderToStaticMarkup(
    <ThemeProvider theme="light"><DataTable data={[]} columns={[{ id: 'name', name: 'Имя' }]} /></ThemeProvider>,
  );
  expect(html).toContain('Нет записей');
});
